#!/usr/bin/env python3
# Pinneberg-Kachel: Statusdatei, API und /funk lesen sie. Kein Alarm, kein Mesh.
from __future__ import annotations
import base64, hashlib, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
PI = {
    "dashboard.py": ("239bdf4d0f761325", 1392013),
    "blackout_radar.py": ("4ff38da718afed9d", 84127),
    "lage_pages.py": ("e9ea014b5a4ff121", 230936),
}
RX_BASIS = ("50fe27dc02b89119", 18686)
ROLLE_BASIS = ("2fb1af4ccd333e65", 10008)
SDR_BASIS = ("e21a0a644a3fc6e3", 777297)
CHECK = ("blackout_radar.py", "lage_pages.py", "prepper_sdr.py")
WRITE = ("pinneberg_rx.py", "pinneberg_rolle.py", "dashboard.py")


def load():
    raw = PAYLOAD_JSON
    rx = (base64.b64decode(raw["rx"]["old"]), base64.b64decode(raw["rx"]["new"]))
    rolle = (base64.b64decode(raw["rolle"]["old"]), base64.b64decode(raw["rolle"]["new"]))
    dash = [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in raw["dash"]]
    return rx, rolle, dash


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def minute(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    return jetzt.minute, "Berlin Minute %02d" % jetzt.minute


def fenster(now=None):
    m, text = minute(now)
    return (not (m >= 45 or m <= 4)), text


def neustart_frei(now=None):
    """Dashboard-Import dauert. Nicht starten, wenn er in Minute 45 laufen wuerde."""
    m, text = minute(now)
    return (4 < m < 40), text


def verwandle(data, pairs):
    if all(data.count(neu) == 1 and data.count(old) == 0 for old, neu in pairs):
        return data
    neu_data = data
    for old, neu in pairs:
        if neu_data.count(neu) == 1 and neu_data.count(old) == 0:
            continue
        if neu_data.count(old) != 1 or neu_data.count(neu) != 0:
            raise RuntimeError("Stelle")
        vor = neu_data
        neu_data = neu_data.replace(old, neu, 1)
        if neu_data.replace(neu, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    return neu_data


def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-pnkachel-*"))
    bak = path.with_name(path.name + ".bak-pnkachel-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass


def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777
    tmp = path.with_name("." + path.name + ".tmp-pnkachel")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass


def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None) -> int:
    rx_pair, rolle_pair, dash_pairs = load()
    erwartet = dict(PI)
    erwartet["prepper_sdr.py"] = SDR_BASIS
    falsch = False
    blobs = {}
    namen = WRITE + CHECK
    for name in namen:
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
        data = pfad.read_bytes()
        blobs[name] = data
        ist = sha(data)
        print("%s sha16 %s bytes %d" % (name, ist[:16], len(data)))
        if name in ("blackout_radar.py", "lage_pages.py", "prepper_sdr.py"):
            kopf, laenge = erwartet[name]
            if not ist.startswith(kopf) or len(data) != laenge:
                print("STOP: %s %s / %d ist nicht der Pi-Stand %s / %d" % (name, ist[:16], len(data), kopf, laenge))
                falsch = True
    if falsch:
        print("STOP: Hash-Guard. Nichts geschrieben.")
        return 2
    rx_old, rx_new = rx_pair
    rx = blobs["pinneberg_rx.py"]
    if rx == rx_new:
        rx_ziel = rx
    elif rx == rx_old and sha(rx).startswith(RX_BASIS[0]) and len(rx) == RX_BASIS[1]:
        rx_ziel = rx_new
    else:
        print("STOP: pinneberg_rx.py %s / %d passt nicht zum Stand %s / %d. Nichts geschrieben." % (sha(rx)[:16], len(rx), RX_BASIS[0], RX_BASIS[1]))
        return 2
    ro_old, ro_new = rolle_pair
    rolle = blobs["pinneberg_rolle.py"]
    rolle_ist = sha(rolle)
    if rolle == ro_new:
        rolle_ziel = rolle
    elif rolle == ro_old:
        rolle_ziel = ro_new
    else:
        print("Hinweis: pinneberg_rolle.py ist %s / %d, der Stand 12.11. ist %s / %d." % (rolle_ist[:16], len(rolle), ROLLE_BASIS[0], ROLLE_BASIS[1]))
        print("STOP: pinneberg_rolle.py passt nicht zum Stand 12.11. Nichts geschrieben.")
        return 2
    if not rolle_ist.startswith(ROLLE_BASIS[0]) and rolle != ro_new:
        print("Hinweis: pinneberg_rolle.py weicht vom notierten Stand ab.")
    try:
        dash_ziel = verwandle(blobs["dashboard.py"], dash_pairs)
    except RuntimeError:
        print("STOP: Anker in dashboard.py fehlt (Kacheltext oder _fua_pin). Hash %s / %d. Nichts geschrieben." % (sha(blobs["dashboard.py"])[:16], len(blobs["dashboard.py"])))
        return 2
    if blobs["dashboard.py"] != dash_ziel:
        kopf, laenge = PI["dashboard.py"]
        ist = sha(blobs["dashboard.py"])
        if not ist.startswith(kopf) or len(blobs["dashboard.py"]) != laenge:
            print("STOP: dashboard.py %s / %d ist nicht der Pi-Stand %s / %d. Nichts geschrieben." % (ist[:16], len(blobs["dashboard.py"]), kopf, laenge))
            return 2
    try:
        compile(rx_ziel, "pinneberg_rx.py", "exec")
        compile(rolle_ziel, "pinneberg_rolle.py", "exec")
        compile(dash_ziel, "dashboard.py", "exec")
    except SyntaxError as exc:
        print("STOP: Syntax %s" % exc)
        return 2
    if b"pinneberg_status.json" not in rx_ziel or b"Text empfangen" not in rx_ziel:
        print("STOP: Statusdatei fehlt")
        return 2
    if b"def kachel" not in rolle_ziel:
        print("STOP: Kachel-Leser fehlt")
        return 2
    if b"(d&&d.txt)?d.txt" not in dash_ziel or b"status_view" not in dash_ziel:
        print("STOP: Kachel-Anzeige fehlt")
        return 2
    print("pinneberg_rx.py endstand sha16 %s bytes %d" % (sha(rx_ziel)[:16], len(rx_ziel)))
    print("pinneberg_rolle.py endstand sha16 %s bytes %d" % (sha(rolle_ziel)[:16], len(rolle_ziel)))
    print("dashboard.py endstand sha16 %s bytes %d" % (sha(dash_ziel)[:16], len(dash_ziel)))
    for name in CHECK:
        print("%s unveraendert sha16 %s bytes %d" % (name, sha(blobs[name])[:16], len(blobs[name])))
    frei, meldung = fenster(jetzt)
    print(meldung)
    ziel = {"pinneberg_rx.py": rx_ziel, "pinneberg_rolle.py": rolle_ziel, "dashboard.py": dash_ziel}
    if all(blobs[name] == ziel[name] for name in WRITE):
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        if not frei:
            print("Ein echtes Apply wuerde in dieser Minute ohne Aenderung abbrechen.")
        print("Nach dem Einspielen, Minute 05 bis 39: systemctl restart prepper-sdr.service && systemctl restart prepper-dashboard.service")
        print("Pruefung: curl -sS http://127.0.0.1:5000/api/pinneberg")
        return 0
    if not frei:
        print("STOP: Neustart-Sperre Minute 45-59 und 00-04 Berlin. Nichts geschrieben.")
        return 2
    try:
        for name in WRITE:
            if blobs[name] != ziel[name]:
                sichern(ordner / name, blobs[name])
                schreiben(ordner / name, ziel[name])
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    print("geschrieben. prepper-sdr und prepper-dashboard muessen neu starten.")
    if kein:
        print("Kein Neustart in dieser Pruefung. Danach in Minute 05 bis 39:")
        print("systemctl restart prepper-sdr.service && systemctl restart prepper-dashboard.service")
        print("Pruefung: curl -sS http://127.0.0.1:5000/api/pinneberg")
        return 0
    darf, meldung = neustart_frei()
    print(meldung)
    if not darf:
        print("Dateien sind neu. Neustart bleibt aus, der Dashboard-Import wuerde in die Sperre laufen.")
        print("Nach Minute 05: systemctl restart prepper-sdr.service && systemctl restart prepper-dashboard.service")
        return 2
    __import__("subprocess").run(["systemctl", "restart", "prepper-sdr.service"], check=False)
    darf, meldung = neustart_frei()
    print(meldung)
    if not darf:
        print("prepper-sdr neu gestartet. prepper-dashboard bleibt, die Sperre hat begonnen.")
        return 2
    __import__("subprocess").run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("prepper-sdr und prepper-dashboard neu gestartet.")
    print("Pruefung: curl -sS http://127.0.0.1:5000/api/pinneberg")
    return 0


def selftest() -> int:
    global SDR_BASIS
    assert PI["dashboard.py"] == ("239bdf4d0f761325", 1392013)
    assert PI["blackout_radar.py"] == ("4ff38da718afed9d", 84127)
    assert PI["lage_pages.py"] == ("e9ea014b5a4ff121", 230936)
    assert RX_BASIS == ("50fe27dc02b89119", 18686)
    assert ROLLE_BASIS == ("2fb1af4ccd333e65", 10008)
    assert SDR_BASIS == ("e21a0a644a3fc6e3", 777297)
    assert fenster(datetime(2026, 11, 20, 20, 12))[0]
    assert not fenster(datetime(2026, 11, 20, 20, 45))[0]
    assert not fenster(datetime(2026, 11, 20, 20, 0))[0]
    assert neustart_frei(datetime(2026, 11, 20, 20, 12))[0]
    assert not neustart_frei(datetime(2026, 11, 20, 20, 40))[0]
    assert not neustart_frei(datetime(2026, 11, 20, 20, 4))[0]
    rx_pair, rolle_pair, dash_pairs = load()
    assert b"pinneberg_status.json" in rx_pair[1] and b"STATUS_NAME" not in rx_pair[0]
    assert b"def kachel" in rolle_pair[1]
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="pnkachel-"))
    (ordner / "pinneberg_rx.py").write_bytes(rx_pair[0])
    (ordner / "pinneberg_rolle.py").write_bytes(rolle_pair[0])
    (ordner / "dashboard.py").write_bytes(b"falsch")
    for name in CHECK:
        (ordner / name).write_bytes(b"falsch")
    vorher = {name: (ordner / name).read_bytes() for name in WRITE + CHECK}
    assert apply_dir(ordner, True, True, datetime(2026, 11, 20, 20, 12)) == 2
    assert vorher == {name: (ordner / name).read_bytes() for name in vorher}
    merk = dict(PI)
    merk_sdr = SDR_BASIS
    try:
        dash_alt = b"VOR\n" + b"\n".join(o for o, _n in dash_pairs) + b"\nNACH\n"
        # echte Dashboard-Anker stecken im Empfaenger-Test weiter unten; hier nur der Abbruch
        (ordner / "dashboard.py").write_bytes(dash_alt)
        teil = b"basis-dashboard"
        blob = (teil * (merk["dashboard.py"][1] // len(teil) + 1))[:merk["dashboard.py"][1]]
        (ordner / "dashboard.py").write_bytes(blob)
        PI["dashboard.py"] = (sha(blob)[:16], len(blob))
        for name, laenge in (("blackout_radar.py", merk["blackout_radar.py"][1]), ("lage_pages.py", merk["lage_pages.py"][1])):
            roh = (b"basis-" + name.encode())
            daten = (roh * (laenge // len(roh) + 1))[:laenge]
            (ordner / name).write_bytes(daten)
            PI[name] = (sha(daten)[:16], len(daten))
        sdr = b"prepper-unveraendert"
        (ordner / "prepper_sdr.py").write_bytes(sdr)
        merk_sdr = SDR_BASIS
        SDR_BASIS = (sha(sdr)[:16], len(sdr))
        # Anker fehlen in dem Fuellstand: Stop, nichts schreiben
        vorher = {name: (ordner / name).read_bytes() for name in WRITE + CHECK}
        assert apply_dir(ordner, False, True, datetime(2026, 11, 20, 20, 12)) == 2
        assert vorher == {name: (ordner / name).read_bytes() for name in vorher}
    finally:
        SDR_BASIS = merk_sdr
        PI.clear()
        PI.update(merk)
    print("selftest ok")
    return 0


def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)


